-- PT113-S3-Q2. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT113-S3-Q2$batch04$ AND q.stimulus=$batch04$For the last three years, entomologists have been searching for a parasite to help control a whitefly that has recently become a serious crop pest. Believing this new pest to be a variety of sweet-potato whitefly, the entomologists confined their search to parasites of the sweet-potato whitefly. Genetic research now shows the new pest to be a distinct species, the silverfleaf whitefly. Therefore, the search for a parasite has so far been wasted effort.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the argument relies?$batch04$ AND q.correct_choice=$batch04$D$batch04$) THEN RAISE EXCEPTION 'Question changed: PT113-S3-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT113-S3-Q2$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S3-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT113-S3-Q2$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$The search for a parasite has so far been wasted effort.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$The entomologists searched only among parasites of the sweet-potato whitefly. The pest turned out to be a different species, the silverleaf whitefly.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$A wrong species does not automatically make the search useless. If some parasites attack both species, the search could still have found one that works.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: no sweet-potato whitefly parasite also attacks the silverleaf whitefly.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT113-S3-Q2$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Whether every variety of sweet-potato whitefly is a pest does not affect the search for a parasite of the silverleaf.$batch04$), ($batch04$B$batch04$, $batch04$The argument does not need a parasite to *always* control its pest.$batch04$), ($batch04$C$batch04$, $batch04$Better chances in the future do not tell us whether the past search was wasted.$batch04$), ($batch04$D$batch04$, $batch04$Negate it: *some* parasite of the sweet-potato whitefly also attacks the silverleaf whitefly. Then the search may have turned up something useful after all, so it was not necessarily wasted.$batch04$), ($batch04$E$batch04$, $batch04$If they found sweet-potato parasites that do not affect the new pest, the search could still be wasted. The argument does not need them to have found nothing.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT113-S3-Q2$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
